This Terraform configuration creates an AWS CloudWatch Metric Alarm that monitors average EC2 CPU utilization across the account/region. The alarm enters the `ALARM` state if CPU utilization exceeds the configured threshold for the configured evaluation periods.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the CloudWatch alarm will be created."
  type        = string
  default     = "us-east-1"
}

variable "alarm_name" {
  description = "Name of the CloudWatch Metric Alarm."
  type        = string
  default     = "ec2-high-cpu-utilization-alarm"
}

variable "cpu_threshold" {
  description = "CPU utilization percentage threshold that triggers the alarm."
  type        = number
  default     = 80
}

variable "evaluation_periods" {
  description = "Number of periods over which data is compared to the threshold."
  type        = number
  default     = 2
}

variable "period" {
  description = "Period in seconds over which the metric statistic is applied."
  type        = nu
